using System.Net;
using Autonogrammer.Api.DataPlane;
using Autonogrammer.Api.Hosting;
using Autonogrammer.Api.IntegrationTests.Hosting;
using Autonogrammer.Api.Options;
using Autonogrammer.Resilience;
using Autonogrammer.Sessions;
using Autonogrammer.Sessions.Postgres;
using Autonogrammer.Sessions.Postgres.Migrations;
using Microsoft.AspNetCore.TestHost;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using Microsoft.Extensions.Logging.Abstractions;
using Npgsql;
using Shouldly;
using Xunit;
using MsOptions = Microsoft.Extensions.Options.Options;

namespace Autonogrammer.Api.IntegrationTests.DataPlane;

/// <summary>
/// D-57: the startup gate probes the session store through the PostgreSQL pipeline, so while the breaker is open the probes fail fast and the first half-open probe
/// after the open window closes the breaker and opens the gate. The host never crashes. The whole run is on a manual clock: no test step sleeps.
/// </summary>
public sealed class DataPlaneStartupGateTests
{
    private static readonly TimeSpan Step = StartupGateHostedService.RetryInterval;

    /// <summary>Verifies the gate opens within one breaker open window after the store recovers, and the host stays up throughout.</summary>
    [Fact]
    public async Task Gate_OpensWithinOneOpenWindowAfterRecovery_AndTheHostNeverCrashes()
    {
        var testToken = TestContext.Current.CancellationToken;
        var time = new ManualTimeProvider();
        var options = new PostgresResilienceOptions { MaxRetries = 0 };
        var pipeline = PostgresResilience.Create(options, time).Pipeline;
        var storeUp = false;
        var repository = new PipelinedSessionRepository(
            pipeline,
            _ => storeUp ? Task.FromResult<Autonogrammer.Contracts.Sessions.Session?>(null) : throw new IOException("The store is down."));

        var app = await HostingTestHost.StartAsync(
            testToken,
            configureServices: services =>
            {
                _ = services.AddSingleton<TimeProvider>(time);
                _ = services.AddSingleton<ISessionRepository>(repository);
            }).ConfigureAwait(true);
        await using var appScope = app.ConfigureAwait(true);
        var gate = app.Services.GetRequiredService<HostingStartupGate>();
        WaitForProbe(repository, time, 1);

        // Five consecutive failures open the breaker; further probes fail fast and never reach the store.
        for (var probe = 2; probe <= 8; probe++)
        {
            time.Advance(Step);
            WaitForProbe(repository, time, probe);
        }

        pipeline.State.ShouldBe(DependencyState.Open);
        repository.Reached.ShouldBe(ResilienceOptions.BreakerConsecutiveFailures);
        gate.IsOpen.ShouldBeFalse();
        (await StatusAsync(app, testToken).ConfigureAwait(true)).ShouldBe(HttpStatusCode.ServiceUnavailable);

        // The store recovers. The breaker stays open for its window, then one probe closes it and the gate opens.
        storeUp = true;
        var recovered = time.GetUtcNow();
        var probes = repository.Completed;
        while (!gate.IsOpen && time.GetUtcNow() - recovered <= TimeSpan.FromSeconds(options.BreakerOpenSeconds) + Step)
        {
            time.Advance(Step);
            WaitForProbe(repository, time, ++probes, () => gate.IsOpen);
        }

        gate.IsOpen.ShouldBeTrue("the gate opens within one breaker open window after recovery");
        repository.Reached.ShouldBe(ResilienceOptions.BreakerConsecutiveFailures + 1, "only the half-open probe reaches the recovered store; the open breaker refused the probes before it");
        pipeline.State.ShouldBe(DependencyState.Healthy);
        (await StatusAsync(app, testToken).ConfigureAwait(true)).ShouldBe(HttpStatusCode.OK);
    }

    /// <summary>Exercises gaps, checksum mismatches and the actual schema wait using independently privileged roles and real migration steps.</summary>
    [Fact]
    [Trait("Category", "Live")]
    public async Task SchemaWait_RequiresActualRegisteredMigrations_InNonContiguousLedgers()
    {
        var token = TestContext.Current.CancellationToken;
        var schema = await LedgerSchema.CreateAsync(token).ConfigureAwait(true);
        await using var schemaScope = schema.ConfigureAwait(true);
        await schema.RunAsync(MigrationRegistry.All.Where(static step => step.Version <= 9).ToArray(), token).ConfigureAwait(true);
        await schema.ExecuteAsync("INSERT INTO schema_migrations(version, name, checksum) VALUES (12, 'future', 'future')", token).ConfigureAwait(true);
        var current = schema.Probe(MigrationRegistry.All);
        (await current.GetAsync(true, token).ConfigureAwait(true)).ShouldBe(SchemaState.Behind);
        await AssertWaitExpiresAsync(current, token).ConfigureAwait(true);

        await schema.RunAsync(MigrationRegistry.All, token).ConfigureAwait(true);
        (await current.GetAsync(true, token).ConfigureAwait(true)).ShouldBe(SchemaState.Ahead);
        var ten = (IMigrationStep)Activator.CreateInstance(
            typeof(MigrationRunner).Assembly.GetType("Autonogrammer.Sessions.Postgres.Migrations.M0010_DispatchDeviceState", throwOnError: true)!,
            nonPublic: true)!;
        var future = MigrationRegistry.All.Append(ten).OrderBy(static step => step.Version).ToArray();
        var later = schema.Probe(future);
        (await later.GetAsync(true, token).ConfigureAwait(true)).ShouldBe(SchemaState.Behind);
        await AssertWaitOpensAfterMigrationAsync(schema, later, future, token).ConfigureAwait(true);

        await schema.ExecuteAsync("UPDATE schema_migrations SET checksum = 'wrong' WHERE version = 11", token).ConfigureAwait(true);
        (await later.GetAsync(true, token).ConfigureAwait(true)).ShouldBe(SchemaState.Behind);
        await AssertWaitExpiresAsync(later, token).ConfigureAwait(true);
    }

    private static async Task AssertWaitExpiresAsync(SchemaHeadProbe probe, CancellationToken token)
    {
        var time = new ManualTimeProvider();
        var lifetime = new TestLifetime();
        var exit = new TestExit();
        using var service = CreateWait(probe, time, lifetime, exit);
        await service.StartAsync(token).ConfigureAwait(true);
        WaitForTimer(time);
        service.ExecuteTask!.IsCompleted.ShouldBeFalse();
        time.Advance(TimeSpan.FromSeconds(2));
        await service.ExecuteTask.WaitAsync(TimeSpan.FromSeconds(30), token).ConfigureAwait(true);
        exit.Code.ShouldBe(1);
        lifetime.Stopped.ShouldBeTrue();
    }

    private static async Task AssertWaitOpensAfterMigrationAsync(LedgerSchema schema, SchemaHeadProbe probe, IReadOnlyList<IMigrationStep> steps, CancellationToken token)
    {
        var time = new ManualTimeProvider();
        var lifetime = new TestLifetime();
        var exit = new TestExit();
        using var service = CreateWait(probe, time, lifetime, exit, waitSeconds: 30);
        await service.StartAsync(token).ConfigureAwait(true);
        WaitForTimer(time);
        service.ExecuteTask!.IsCompleted.ShouldBeFalse();
        var applied = await schema.RunAsync(steps, token).ConfigureAwait(true);
        applied.Count.ShouldBe(1);
        applied[0].ShouldBe(10);
        (await probe.GetAsync(true, token).ConfigureAwait(true)).ShouldBe(SchemaState.Ahead);
        time.Advance(TimeSpan.FromSeconds(2));
        await service.ExecuteTask.WaitAsync(TimeSpan.FromSeconds(30), token).ConfigureAwait(true);
        exit.Code.ShouldBeNull();
        lifetime.Stopped.ShouldBeFalse();
    }

    private static SchemaHeadWaitService CreateWait(SchemaHeadProbe probe, ManualTimeProvider time, TestLifetime lifetime, TestExit exit, int waitSeconds = 2) =>
        new(probe, MsOptions.Create(new DataPlaneOptions { Postgres = { SchemaWaitSeconds = waitSeconds } }),
            MsOptions.Create(new SessionsOptions { Store = SessionsOptions.PostgresStore }), lifetime, exit, time, NullLogger<SchemaHeadWaitService>.Instance);

    private static void WaitForTimer(ManualTimeProvider time) =>
        SpinWait.SpinUntil(() => time.PendingTimers > 0, TimeSpan.FromSeconds(30)).ShouldBeTrue("the schema wait did not schedule a retry");

    private sealed class TestExit : IExitCodeSink
    {
        public int? Code { get; private set; }

        public void Set(int exitCode) => Code = exitCode;
    }

    private sealed class TestLifetime : IHostApplicationLifetime
    {
        public CancellationToken ApplicationStarted => CancellationToken.None;

        public CancellationToken ApplicationStopping => CancellationToken.None;

        public CancellationToken ApplicationStopped => CancellationToken.None;

        public bool Stopped { get; private set; }

        public void StopApplication() => Stopped = true;
    }

    private sealed class LedgerSchema : IAsyncDisposable
    {
        private readonly string _schema = "t_" + Guid.NewGuid().ToString("n");
        private readonly string _role = "r_" + Guid.NewGuid().ToString("n");
        private readonly string _password = Guid.NewGuid().ToString("n") + Guid.NewGuid().ToString("n");
        private readonly NpgsqlDataSource _admin;
        private NpgsqlDataSource? _reader;

        private LedgerSchema(string connection) => _admin = NpgsqlDataSource.Create(connection);

        public static async Task<LedgerSchema> CreateAsync(CancellationToken token)
        {
            var connection = Environment.GetEnvironmentVariable("AUTONOGRAMMER_TEST_POSTGRES_CONNECTION");
            if (!string.Equals(Environment.GetEnvironmentVariable("AUTONOGRAMMER_TEST_POSTGRES_RUN_OWNED"), "1", StringComparison.Ordinal) || string.IsNullOrWhiteSpace(connection))
            {
                throw new InvalidOperationException("A verified run-owned PostgreSQL connection and AUTONOGRAMMER_TEST_POSTGRES_RUN_OWNED=1 are required.");
            }

            var builder = new NpgsqlConnectionStringBuilder(connection);
            if (builder.Host is not ("localhost" or "127.0.0.1" or "::1"))
            {
                throw new InvalidOperationException("The run-owned PostgreSQL service must use a loopback host.");
            }

            var result = new LedgerSchema(connection);
            try
            {
                await result.ExecuteAdminAsync($"""
                    CREATE SCHEMA "{result._schema}";
                    CREATE ROLE "{result._role}" LOGIN PASSWORD '{result._password}' NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
                    GRANT USAGE ON SCHEMA "{result._schema}" TO "{result._role}";
                    """, token).ConfigureAwait(false);
                result._reader = NpgsqlDataSource.Create(new NpgsqlConnectionStringBuilder(connection)
                {
                    Username = result._role,
                    Password = result._password,
                    SearchPath = result._schema + ",public",
                }.ConnectionString);
                return result;
            }
            catch
            {
                await result.DisposeAsync().ConfigureAwait(false);
                throw;
            }
        }

        public async Task<IReadOnlyList<int>> RunAsync(IReadOnlyList<IMigrationStep> steps, CancellationToken token)
        {
            var applied = await new MigrationRunner(_admin, _schema, steps).MigrateAsync(token).ConfigureAwait(false);
            await ExecuteAdminAsync($"GRANT SELECT ON \"{_schema}\".schema_migrations TO \"{_role}\"", token).ConfigureAwait(false);
            var check = _reader!.CreateCommand("""
                SELECT NOT rolsuper AND NOT rolcreatedb AND NOT rolcreaterole
                    AND NOT has_schema_privilege(current_user, current_schema(), 'CREATE')
                    AND has_table_privilege(current_user, 'schema_migrations', 'SELECT')
                    AND NOT has_table_privilege(current_user, 'schema_migrations', 'UPDATE')
                FROM pg_roles WHERE rolname = current_user
                """);
            await using var checkScope = check.ConfigureAwait(false);
            (await check.ExecuteScalarAsync(token).ConfigureAwait(false)).ShouldBe(true);
            return applied;
        }

        public SchemaHeadProbe Probe(IReadOnlyList<IMigrationStep> steps)
        {
            var runner = new MigrationRunner(_reader!, _schema, steps);
            return new SchemaHeadProbe(runner.ListAppliedAsync, steps, true, TimeProvider.System);
        }

        public Task ExecuteAsync(string sql, CancellationToken token) => ExecuteAdminAsync($"SET search_path TO \"{_schema}\", public; {sql}", token);

        public async ValueTask DisposeAsync()
        {
            if (_reader is not null)
            {
                await _reader.DisposeAsync().ConfigureAwait(false);
            }

            await ExecuteAdminAsync($"DROP SCHEMA IF EXISTS \"{_schema}\" CASCADE; DROP ROLE IF EXISTS \"{_role}\"", CancellationToken.None).ConfigureAwait(false);
            await _admin.DisposeAsync().ConfigureAwait(false);
        }

        private async Task ExecuteAdminAsync(string sql, CancellationToken token)
        {
            var command = _admin.CreateCommand(sql);
            await using var commandScope = command.ConfigureAwait(false);
            await command.ExecuteNonQueryAsync(token).ConfigureAwait(false);
        }
    }

    private static async Task<HttpStatusCode> StatusAsync(Microsoft.AspNetCore.Builder.WebApplication app, CancellationToken cancellationToken)
    {
        using var client = app.GetTestClient();
        using var response = await client.GetAsync(new Uri("/health/startup", UriKind.Relative), cancellationToken).ConfigureAwait(false);
        return response.StatusCode;
    }

    /// <summary>
    /// Waits, by yielding the processor and not by sleeping, until the probe with number <paramref name="probe"/> has ended and the gate loop has armed its next
    /// delay timer (or <paramref name="done"/> says the loop ended). A hard limit on real time only guards against a hung test.
    /// </summary>
    private static void WaitForProbe(PipelinedSessionRepository repository, ManualTimeProvider time, int probe, Func<bool>? done = null)
    {
        var reached = SpinWait.SpinUntil(
            () => repository.Completed >= probe && (time.PendingTimers > 0 || (done?.Invoke() ?? false)),
            TimeSpan.FromSeconds(30));
        reached.ShouldBeTrue($"probe {probe} did not end and re-arm the gate delay");
    }
}
